/**
 * Site-wide stats — the single source of truth.
 *
 * Every number here comes from `docs/stats.json`, the repo's single source of
 * truth, generated by `scripts/docs-stats.mjs` and kept fresh by
 * `scripts/check-doc-stats.mjs` in CI. Do NOT hardcode counts in this file,
 * components, or the i18n dictionary — they drift and nobody notices.
 * (This file previously hardcoded 63 packages / 27 UI packages while the repo
 * actually had 72 / 36.)
 *
 * stars is the one exception: it is not derivable from the repo, so it is
 * updated by hand from https://api.github.com/repos/louloulin/OpenBuddy.
 */
import repoStats from '../../../../docs/stats.json';

export const SITE_STATS = {
  packages: repoStats.openbuddyPackages,
  uiPackages: repoStats.openbuddyUiPackages,
  collaborationPackages: repoStats.openbuddyCollaborationPackages,
  testFiles: repoStats.testFiles,
  stars: 9
} as const;

export const SITE_LICENSE = 'MIT' as const;

/**
 * Canonical origin for absolute URLs (canonical tags, hreflang, sitemap,
 * robots). Read from the environment so a preview deploy advertises its own
 * origin instead of the production one; the literal is the production
 * fallback for builds that do not set it.
 */
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || 'https://openbuddy.dev').replace(/\/+$/, '');
